// Fun Gradient Pallet Generator
vec3 pal(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);

    return a + b*cos(6.28318*(c*t+d));
}

// Rotation matrix function
mat2 rotate(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, -s, s, c);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //NORMALIZE UV from -1 to 1 
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    // Get time as T.
    float t = iTime * 1.0;

    // Final Color
    vec3 finCol = vec3(0.,0.,0.);


    // -------------------------//
    //         MOD VALS         //
    // -------------------------//
    float intensity = .99;
    float size = .2;
    float jitter = .99;
    float count = 0.15;

    // -------------------------//
    //      NORMALIZE MODS      //
    // -------------------------//
    intensity = intensity * 99. + 5.;
    size *= 10.0;
    jitter *= 80.0;

    // -------------------------//
    //         DO CODE          //
    // -------------------------//

    vec3 col = vec3(0.0, 0.0, 0.0);

    // Number of copies
    float numCopies = 70.0;

    // Spacing between copies


    for (float i = 0.0; i<intensity; i++) {

        vec2 offsetUV = uv;
        // Move each copy
        offsetUV.x += i * count * uv.y * sin(2.3152*t);
        offsetUV.y += i * count * uv.x * sin(4.631*t);

        if (offsetUV.x < -1.2) {
            offsetUV.x += count * fract(t);
        }

        // Get the distance of UV from the center
        float d = length(offsetUV);
        d = step(d, 0.08*size+(sin(jitter*t)*.01));

        // Blend color based on palette
        vec3 col = pal(-t + i * 0.05) * d; 

        // Accumulate colors
        finCol += col;
    }


    fragColor = vec4(finCol, 1.0);
}
